import{_ as n,c as a,o as t,ag as i}from"./chunks/framework.ARG558ZT.js";const h=JSON.parse('{"title":"Node.js workbench","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/node-js/index.md","filePath":"workbench/node-js/index.md"}'),r={name:"workbench/node-js/index.md"};function o(s,e,d,c,l,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="node-js-workbench" tabindex="-1">Node.js workbench <a class="header-anchor" href="#node-js-workbench" aria-label="Permalink to “Node.js workbench”">​</a></h1><p>Reference implementations support the <a href="./../../node-js/">textbook</a>; independent assignments live in <a href="./../../practice/node-js/">practice</a>. Reading or executing a reference is not learner completion.</p><p>See the <a href="./runtime/">rendered runtime source collection and run instructions</a>.</p><h2 id="runtime-references" tabindex="-1">Runtime references <a class="header-anchor" href="#runtime-references" aria-label="Permalink to “Runtime references”">​</a></h2><ul><li><a href="./runtime/modules.html">Module boundary and interoperability collection</a>.</li><li><code>runtime/limiter.ts</code>: bounded admission, original failure, cooperative abort and active-worker drain.</li><li><code>runtime/worker.ts</code>: one-result worker, runtime result parser, termination and cleanup.</li><li><code>runtime/json-lines.ts</code>: bounded byte frames, strict UTF-8 and nonnull object output.</li><li><code>runtime/child.ts</code>: one owned child; settle at close, including startup/abort failure.</li></ul><p>These sources are included directly in their teaching pages, so the displayed implementation and canonical source agree. Compile TypeScript using the documented compatible compiler/types, then run JavaScript; native type stripping is not a substitute for type checking.</p><p>Reference scope matters: the limiter is a bounded array batch, the worker is not a pool, the parser is not a domain validator, and the child helper does not own a process tree. Backend/database/deployment fixtures have separate dependency and environment requirements.</p><h2 id="backend-and-persistence-collections" tabindex="-1">Backend and persistence collections <a class="header-anchor" href="#backend-and-persistence-collections" aria-label="Permalink to “Backend and persistence collections”">​</a></h2><ul><li><a href="./backend/products-api.html">Products API</a>: one multi-file Express/in-memory architecture reference; public synthetic storage, not an authenticated production API.</li><li><a href="./backend/session-app.html">Session application</a>: includes the existing <code>examples/node-textbook/src/app.ts</code>; its sibling source/README/lock remain canonical and runnable together.</li><li><a href="./backend/rest-contracts.html">REST/OpenAPI</a>: generation, drift and actual HTTP checks; supporting files are under <code>backend/contract-lab/</code>.</li><li><a href="./database/sql-queries.html">SQL query collection</a>: one disposable schema, parameter binding and expected report results.</li><li><code>database/pagination/</code> and <code>database/redis/</code>: source included in their <a href="./../../node-js/cursor-pagination.html">pagination</a> and <a href="./../../node-js/redis-adapters.html">Redis</a> explanations. Redis remains an alternative.</li></ul><h2 id="security-messaging-and-deployment" tabindex="-1">Security, messaging and deployment <a class="header-anchor" href="#security-messaging-and-deployment" aria-label="Permalink to “Security, messaging and deployment”">​</a></h2><ul><li><code>security/csp/</code> and <code>security/uploads/</code>: typed sources included in the CSP/upload lessons.</li><li><code>security/upload-lab/</code> and <code>security/webhook-lab/</code>: runnable parser/HTTP/PostgreSQL fixtures with their existing checks.</li><li><code>messaging/jobs-lab/</code>: RabbitMQ/outbox and PostgreSQL scheduler examples. Run <code>node ownership.check.mjs</code> from that fixture directory after its locked install for startup/publication cleanup failure checks without a live broker. The <a href="./../../node-js/jobs-and-schedules.html">jobs lesson</a> defines dependencies, uncertain windows and operational limits.</li><li><code>deployment/container-lab/</code> and <code>deployment/full-stack-lab/</code>: copy both dependency-complete directories as directed by the <a href="./../../node-js/full-stack-deployment.html">deployment lesson</a>. Setup creates only owned temporary fixture resources. Container locks/hidden setup files stay with their sources.</li></ul><p>A directory of source is not automatically a complete application. Setup paths, exact dependencies, synthetic identities, integration ports and unimplemented deployment adapters are documented in the corresponding lesson. Real database, broker, browser, provider and cloud checks have separate evidence requirements. Do not run fixture reset/cleanup scripts against an existing user database or shared service.</p>',12)])])}const m=n(r,[["render",o]]);export{h as __pageData,m as default};
